import { useEffect, useState } from "react";
import { Box, Container, Stack, Typography } from "@mui/material";
import api, { mediaUrl } from "../services/api";
import type { HomeApp, SingleResponse } from "../types/home";

export default function AppDownload() {
  const [data, setData] = useState<HomeApp | null>(null);

  useEffect(() => {
    api
      .get<SingleResponse<HomeApp>>("/home-app", {
        params: {
          "populate[appStoreImage]": true,
          "populate[playStoreImage]": true,
          "populate[qrImage]": true,
          "populate[sideImage]": true,
        },
      })
      .then((payload) => setData(payload.data || null))
      .catch(() => setData(null));
  }, []);

  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 10 }, backgroundColor: "#f7f9fc" }}>
      <Container maxWidth="lg">
        <Stack direction={{ xs: "column", md: "row" }} alignItems="center" spacing={6}>
          <Box sx={{ flex: 1 }}>
            <Typography sx={{ color: "#17224d", fontSize: { xs: 26, md: 35 }, fontWeight: 600, mb: 2 }}>
              {data.title}
            </Typography>
            <Typography sx={{ color: "#5a6473", fontSize: 16, mb: 3, whiteSpace: "pre-line" }}>
              {data.description}
            </Typography>
            <Stack direction="row" spacing={2} sx={{ mb: 3 }}>
              {data.appStoreUrl && mediaUrl(data.appStoreImage) ? (
                <Box component="a" href={data.appStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box component="img" src={mediaUrl(data.appStoreImage)} alt="App Store" sx={{ height: 48 }} />
                </Box>
              ) : null}
              {data.playStoreUrl && mediaUrl(data.playStoreImage) ? (
                <Box component="a" href={data.playStoreUrl} target="_blank" rel="noopener noreferrer">
                  <Box component="img" src={mediaUrl(data.playStoreImage)} alt="Play Store" sx={{ height: 48 }} />
                </Box>
              ) : null}
            </Stack>
            {mediaUrl(data.qrImage) ? (
              <Box
                component="img"
                src={mediaUrl(data.qrImage)}
                alt="QR"
                sx={{ width: 180, height: 180, display: "block", mb: 1.5 }}
              />
            ) : null}
            <Typography sx={{ color: "#5a6473", fontSize: 16 }}>{data.qrText}</Typography>
          </Box>
          {mediaUrl(data.sideImage) ? (
            <Box sx={{ flex: 1 }}>
              <Box
                component="img"
                src={mediaUrl(data.sideImage)}
                alt={data.sideImage?.alternativeText || "App"}
                sx={{ width: "100%" }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
